%22%20y%3D%220%22%20width%3D%2226%22%20height%3D%2212%22%20rx%3D%226%22/%3E%3Cpath%20d%3D%22M26%206c6%200%208%204%2012%204%22/%3E%3C/g%3E%20%3Ccircle%20cx%3D%22120%22%20cy%3D%2240%22%20r%3D%222.2%22/%3E%3Ccircle%20cx%3D%2296%22%20cy%3D%22230%22%20r%3D%222.2%22/%3E%3Ccircle%20cx%3D%22240%22%20cy%3D%22240%22%20r%3D%223%22/%3E%3Ccircle%20cx%3D%2270%22%20cy%3D%22120%22%20r%3D%221.8%22/%3E%20%3C/svg%3E"); color-scheme:dark}}
