%22%20y%3D%220%22%20width%3D%2226%22%20height%3D%2212%22%20rx%3D%226%22/%3E%3Cpath%20d%3D%22M26%206c6%200%208%204%2012%204%22/%3E%3C/g%3E%20%3Ccircle%20cx%3D%22120%22%20cy%3D%2240%22%20r%3D%222.2%22/%3E%3Ccircle%20cx%3D%2296%22%20cy%3D%22230%22%20r%3D%222.2%22/%3E%3Ccircle%20cx%3D%22240%22%20cy%3D%22240%22%20r%3D%223%22/%3E%3Ccircle%20cx%3D%2270%22%20cy%3D%22120%22%20r%3D%221.8%22/%3E%20%3C/svg%3E"); color-scheme:dark}
*{box-sizing:border-box}
html,body{background:var(--bg)}
body{margin:0;color:var(--ink);font-family:var(--f-body);font-size:15px;line-height:1.75;
  background-color:var(--bg);background-image:var(--doodle);background-size:260px 260px;
  -webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
input,textarea{-webkit-user-select:text;user-select:text}
button{font-family:inherit}
.wrap{max-width:1360px;margin:0 auto;padding-inline:16px}

.top{position:relative;overflow:hidden;color:#fff;
  background:linear-gradient(120deg,#063f33 0%,#0a6b56 48%,#2f8d4a 100%);
  border-bottom:3px solid var(--leaf)}
.top .helix{position:absolute;inset-block:0;inset-inline-end:-40px;width:min(640px,70%);height:100%;opacity:.22;pointer-events:none}
.helix path{fill:none;stroke:#fff;stroke-width:2.4;stroke-linecap:round}
.helix .rungs path{stroke-width:1.6;stroke-dasharray:3 6}
.top-in{position:relative;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding-block:20px 18px}
.brand{display:flex;align-items:center;gap:14px;min-width:0}
.logo{flex:0 0 52px;width:52px;height:52px;border-radius:16px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.28);display:grid;place-items:center}
.logo svg{width:30px;height:30px;fill:none;stroke:#fff;stroke-width:2;stroke-linecap:round}
.brand h1{font-family:var(--f-display);font-weight:700;font-size:clamp(1.6rem,3.4vw,2.3rem);line-height:1.15;margin:0;letter-spacing:.2px}
.brand .by{margin:4px 0 0;font-size:.9rem;opacity:.92}
.brand .by b{font-weight:700}
.stats{display:flex;gap:8px;margin-top:8px;flex-wrap:wrap}
.stat{font-size:.78rem;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.22);border-radius:999px;padding:2px 10px;font-variant-numeric:tabular-nums}
.actions{display:flex;gap:8px;flex-wrap:wrap}
.btn{display:inline-flex;align-items:center;gap:6px;font:inherit;font-size:.86rem;font-weight:600;cursor:pointer;
  border-radius:10px;padding:8px 14px;border:1px solid var(--line);background:var(--paper);color:var(--ink);transition:background .15s,border-color .15s}
.btn:hover{border-color:var(--main)}
.btn.small{padding:5px 11px;font-size:.8rem}
.btn.primary{background:var(--main);border-color:var(--main);color:#fff}
.btn.primary:hover{background:var(--main-d);border-color:var(--main-d)}
:root[data-theme="dark"] .btn.primary{color:#062a21}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]) .btn.primary{color:#062a21}}
.btn.danger{color:var(--danger);border-color:color-mix(in srgb,var(--danger) 45%,transparent);background:transparent}
.btn.danger-solid{background:var(--danger);border-color:var(--danger);color:#fff}
.btn.ghost{background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.32);color:#fff}
.btn.ghost:hover{background:rgba(255,255,255,.22);border-color:#fff}
.btn:focus-visible,.g-btn:focus-visible,.u-btn:focus-visible,.l-item:focus-visible,.add-btn:focus-visible,.extra-toggle:focus-visible{outline:3px solid var(--accent);outline-offset:2px}

.layout{display:grid;grid-template-columns:320px minmax(0,1fr);gap:22px;align-items:start;padding-block:22px 60px}
.tree{position:sticky;top:calc(12px + env(safe-area-inset-top,0px));max-height:calc(100vh - 24px);overflow:auto;
  background:color-mix(in srgb,var(--paper) 92%,transparent);border:1px solid var(--line);border-radius:18px;padding:14px 10px;box-shadow:var(--shadow)}
.tree-h{font-family:var(--f-display);font-weight:600;font-size:1rem;color:var(--main-d);margin:2px 8px 10px}
.g-block+.g-block{margin-top:8px}
.g-btn{width:100%;display:flex;justify-content:space-between;align-items:center;gap:8px;text-align:right;cursor:pointer;
  background:var(--main-l);border:1px solid transparent;border-radius:12px;padding:10px 12px;color:var(--ink)}
.g-btn:hover{border-color:var(--main)}
.g-name{font-weight:700;font-size:.98rem}
.g-meta{font-size:.76rem;color:var(--mute);white-space:nowrap;font-variant-numeric:tabular-nums}
.chev{display:inline-block;transition:transform .2s}
.g-body{display:none;padding:6px 2px 4px}
.g-body.open{display:block}
.g-block:has(.g-body.open) .chev{transform:rotate(180deg)}
.u-btn{width:100%;display:flex;align-items:center;gap:9px;text-align:right;cursor:pointer;background:transparent;border:0;border-radius:10px;padding:7px 8px;color:var(--ink)}
.u-btn:hover{background:var(--main-l)}
.u-num{flex:0 0 26px;height:26px;border-radius:50%;display:grid;place-items:center;font-size:.8rem;font-weight:700;
  border:1.5px solid var(--main);color:var(--main-d);font-variant-numeric:tabular-nums}
.u-name{flex:1;min-width:0;font-size:.88rem;font-weight:600;line-height:1.4}
.u-badge{font-size:.72rem;color:var(--mute);font-variant-numeric:tabular-nums}
.l-list{display:none;margin:2px 0 6px;padding-inline-start:20px;border-inline-start:2px dotted var(--line);margin-inline-start:20px}
.l-list.open{display:block}
.l-item{width:100%;display:flex;justify-content:space-between;align-items:center;gap:8px;text-align:right;cursor:pointer;
  background:transparent;border:0;border-radius:8px;padding:6px 9px;font-size:.84rem;line-height:1.45;color:var(--ink)}
.l-item:hover{background:var(--main-l)}
.l-item.active{background:var(--main);color:#fff;font-weight:700}
:root[data-theme="dark"] .l-item.active{color:#062a21}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]) .l-item.active{color:#062a21}}
.l-item.empty:not(.active){color:var(--mute)}
.l-flag{font-size:.68rem;padding:0 7px;border-radius:999px;background:var(--accent-l);color:var(--accent);white-space:nowrap}
.l-empty{font-size:.8rem;color:var(--mute);padding:6px 9px}
.add-btn{display:block;width:100%;margin:6px 0 2px;padding:5px 9px;font-size:.78rem;text-align:right;cursor:pointer;
  background:transparent;color:var(--main);border:1px dashed var(--line);border-radius:8px}
.add-btn:hover{border-color:var(--main)}

.panel{min-width:0}
.welcome{background:var(--paper);border:1px solid var(--line);border-radius:22px;padding:30px 24px 34px;text-align:center;box-shadow:var(--shadow)}
.welcome h2{font-family:var(--f-display);font-weight:600;font-size:1.5rem;margin:8px 0 6px;text-wrap:balance}
.welcome p{max-width:58ch;margin:0 auto;color:var(--mute)}
.welcome-steps{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:18px}
.welcome-steps span{font-size:.82rem;padding:5px 12px;border-radius:999px;background:var(--main-l);color:var(--main-d)}
.cell-art{width:min(260px,70%);height:auto;display:block;margin:0 auto}
.c-mem{fill:var(--main-l);stroke:var(--main);stroke-width:2.5}
.c-cyto{fill:none;stroke:var(--main);stroke-opacity:.25;stroke-width:1;stroke-dasharray:2 5}
.c-nuc{fill:var(--paper);stroke:var(--main-d);stroke-width:2}
.c-nucl{fill:var(--main);opacity:.55}
.c-er{fill:none;stroke:var(--leaf);stroke-width:2;stroke-linecap:round}
.c-mito rect{fill:var(--accent-l);stroke:var(--accent);stroke-width:1.8}
.c-mito path{fill:none;stroke:var(--accent);stroke-width:1.4}
.c-ves{fill:none;stroke:var(--main);stroke-width:1.6}
.c-ribo{fill:var(--main-d)}
@media (prefers-reduced-motion:no-preference){.cell-art{animation:breathe 6s ease-in-out infinite}
  @keyframes breathe{0%,100%{transform:scale(1)}50%{transform:scale(1.025)}}}

.lesson{background:var(--paper);border:1px solid var(--line);border-radius:22px;padding:20px 20px 24px;box-shadow:var(--shadow)}
.crumb{font-size:.82rem;color:var(--mute)}
.crumb span{margin-inline:4px;color:var(--main)}
.lesson-head{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:4px 0 12px}
.title-in{flex:1 1 280px;min-width:0;font-family:var(--f-display);font-weight:600;font-size:clamp(1.25rem,2.6vw,1.65rem);
  color:var(--ink);background:transparent;border:1px solid transparent;border-radius:10px;padding:4px 8px;margin-inline-start:-8px}
.title-in:hover,.title-in:focus{border-color:var(--line);background:var(--bg);outline:none}
.head-actions{display:flex;gap:8px;flex-wrap:wrap}
.empty-note{background:var(--accent-l);color:var(--ink);border-radius:12px;padding:9px 14px;font-size:.86rem;margin-bottom:12px;border-inline-start:4px solid var(--accent)}
.copybar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;
  background:linear-gradient(120deg,var(--main-l),color-mix(in srgb,var(--main-l) 50%,var(--paper)));border:1px solid color-mix(in srgb,var(--main) 35%,transparent);
  border-radius:16px;padding:14px 16px;margin-bottom:16px}
.copybar-text{display:flex;flex-direction:column;min-width:0;flex:1 1 240px}
.copybar-text strong{font-size:.98rem;color:var(--main-d)}
.copybar-text span{font-size:.82rem;color:var(--mute)}
.copybar-btns{display:flex;gap:8px;flex-wrap:wrap}
.secs{display:grid;gap:12px}
.sec{border:1px solid var(--line);border-radius:14px;padding:12px 14px 12px;background:var(--paper)}
.sec.ess{border-inline-start:4px solid var(--main)}
.sec-head{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:6px}
.sec-head h3{display:flex;align-items:center;gap:8px;margin:0;font-size:.98rem;font-weight:700}
.ic{width:22px;height:22px;flex:0 0 22px;fill:none;stroke:var(--main);stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.sugg{font-size:.7rem;font-weight:700;padding:1px 9px;border-radius:999px;background:var(--accent-l);color:var(--accent);border:1px solid color-mix(in srgb,var(--accent) 40%,transparent)}
.links{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.links a{font-size:.8rem;color:var(--main-d);background:var(--main-l);border-radius:999px;padding:3px 12px;text-decoration:none;direction:rtl;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.links a:hover{text-decoration:underline}
.sec-note{font-size:.74rem;color:var(--leaf);font-weight:600}
.field{width:100%;min-height:88px;field-sizing:content;max-height:420px;resize:vertical;font:inherit;font-size:.9rem;line-height:1.75;color:var(--ink);
  background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:9px 12px}
.field:focus{outline:2px solid var(--main);outline-offset:1px}
.sec-actions{display:flex;gap:6px;margin-top:8px;flex-wrap:wrap}
.extra-toggle{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;width:100%;margin-top:16px;cursor:pointer;text-align:right;
  font:inherit;font-size:.88rem;font-weight:600;color:var(--ink);background:transparent;border:1px dashed var(--line);border-radius:12px;padding:10px 14px}
.extra-toggle:hover{border-color:var(--accent)}
.extra-body{display:grid;gap:12px;margin-top:12px}
.extra-body[hidden]{display:none}
.sec.extra{border-inline-start:4px solid var(--accent);background:color-mix(in srgb,var(--accent-l) 40%,var(--paper))}
.muted{color:var(--mute);font-size:.8rem;font-weight:400}

.settings{background:var(--paper);border:1px solid var(--line);border-radius:22px;padding:20px;box-shadow:var(--shadow);display:grid;gap:12px}
.settings h2{font-family:var(--f-display);font-weight:600;margin:0}
.settings p{margin:0}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin:4px 0 8px}
.chip{display:inline-flex;align-items:center;gap:6px;background:var(--main-l);color:var(--main-d);border-radius:999px;padding:4px 6px 4px 12px;font-size:.84rem}
.chip button{border:0;background:transparent;color:inherit;cursor:pointer;font-size:1rem;line-height:1;padding:0 6px}
.chip-add{display:flex;gap:8px}
.chip-add input{flex:1;min-width:0;font:inherit;font-size:.86rem;padding:6px 10px;border-radius:9px;border:1px solid var(--line);background:var(--bg);color:var(--ink)}

.modal{position:fixed;inset:0;z-index:50;display:grid;place-items:center;padding:16px;background:rgba(6,30,24,.45);backdrop-filter:blur(2px)}
.modal[hidden]{display:none}
[hidden]{display:none!important}
.modal-box{width:min(560px,100%);max-height:calc(100vh - 32px);overflow:auto;background:var(--paper);color:var(--ink);border-radius:18px;padding:18px 18px 16px;border:1px solid var(--line);box-shadow:0 20px 50px rgba(0,0,0,.25)}
.modal-box h3{margin:0 0 6px;font-family:var(--f-display);font-weight:600;font-size:1.2rem}
.m-msg{margin:0 0 10px;color:var(--mute);font-size:.88rem}
.m-input,.m-text{width:100%;font:inherit;font-size:.9rem;padding:8px 11px;border-radius:10px;border:1px solid var(--line);background:var(--bg);color:var(--ink)}
.m-text{min-height:160px;resize:vertical;direction:ltr;text-align:left;font-size:.78rem;font-family:ui-monospace,Menlo,Consolas,monospace}
.m-file{display:block;margin-top:10px;font-size:.84rem;color:var(--mute)}
.m-file input{display:block;margin-top:4px;max-width:100%}
.m-actions{display:flex;gap:8px;justify-content:flex-start;flex-wrap:wrap;margin-top:14px}

.toast{position:fixed;inset-inline:0;bottom:calc(18px + env(safe-area-inset-bottom,0px));margin:auto;width:max-content;max-width:calc(100% - 32px);
  z-index:60;background:var(--ink);color:var(--bg);padding:9px 18px;border-radius:999px;font-size:.86rem;opacity:0;transform:translateY(8px);transition:opacity .2s,transform .2s;pointer-events:none}
.toast.on{opacity:1;transform:none}
.foot{text-align:center;color:var(--mute);font-size:.78rem;padding-block:0 30px}

@media (max-width:860px){
  .layout{grid-template-columns:minmax(0,1fr)}
  .tree{position:static;max-height:none}
  .lesson,.welcome{padding:16px 14px 20px;border-radius:18px}
}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
